/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_reportBytes">_reportBytes</param>
/// <param name = "_printer">_printer</param>
/// <param name = "_dataContract">_dataContract</param>
/// <param name = "_paramArray">_paramArray</param>
/// <param name = "_result">_result</param>
[SubscribesTo(classStr(SRSPrintDestinationSettingsDelegates), delegateStr(SRSPrintDestinationSettingsDelegates, toSendFile))]
public static void SRSPrintDestinationSettingsDelegates_toSendFile(System.Byte[] _reportBytes, SrsReportRunPrinter _printer, SrsReportDataContract _dataContract, Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[] _paramArray, EventHandlerResult _result)
{
    if (_dataContract.parmDoNotSaveFileIM())
    {
        _dataContract.parmReportBytesIM(_reportBytes);
        _result.result(false);
    }
}

/// <summary>
/// designed from
/// </summary>
/// <param name = "_reportName">_reportName</param>
/// <param name = "_reportBytes">_reportBytes</param>
/// <param name = "_printedRecord">_printedRecord</param>
public static void saveToMemory(Name        _reportName,System.Byte[]       _reportBytes, Common    _printedRecord)
{
    AVAERReportToMemory     reportToMemory;
    System.IO.MemoryStream memoryStream = new System.IO.MemoryStream(_reportBytes);
    Binary                 binary =  Binary::constructFromMemoryStream(memoryStream);

    select firstonly reportToMemory
        where reportToMemory.ReportName    == _reportName
           && reportToMemory.RefTableId    == _printedRecord.TableId
           && reportToMemory.RefRecId      == _printedRecord.RecId;

    reportToMemory.ReportName = _reportName;
    reportToMemory.RefTableId = _printedRecord.TableId;
    reportToMemory.RefRecId   = _printedRecord.RecId;
    reportToMemory.Report     = binary.getContainer();

    if (reportToMemory.RecId)
    {
        reportToMemory.selectForUpdate(true);
        ttsbegin;
        reportToMemory.update();
        ttscommit;
    }
    else
    {
        reportToMemory.insert();
    }

}
